    def d(a, b):
        return dist[a][b]

    def route_load(route):
        s = 0
        for x in route:
            s += demands[x]
        return s

    def route_cost(route):
        if not route:
            return 0.0
        c = d(depot, route[0]) + d(route[-1], depot)
        for i in range(len(route) - 1):
            c += d(route[i], route[i + 1])
        return c

    def insertion_cost(route, node, pos):
        prev = depot if pos == 0 else route[pos - 1]
        nxt = depot if pos == len(route) else route[pos]
        return d(prev, node) + d(node, nxt) - d(prev, nxt)

    # Initial seed ordering: farthest from depot, tie by demand and id
    order = sorted(customers, key=lambda x: (-d(depot, x), -demands[x], x))

    # Constructive phase: greedy route building with cheapest insertion
    unassigned = {}
    for c in customers:
        unassigned[c] = 1

    routes = []
    loads = []

    while unassigned:
        seed = None
        for c in order:
            if c in unassigned:
                seed = c
                break
        if seed is None:
            break

        route = [seed]
        load = demands[seed]
        del unassigned[seed]

        while True:
            best_node = None
            best_pos = 0
            best_delta = None

            # Candidate nodes sorted by closeness to current route ends / depot
            cand_list = []
            for c in unassigned:
                if load + demands[c] <= capacity:
                    cand_list.append(c)
            if not cand_list:
                break

            cand_list.sort(key=lambda x: (d(depot, x), -demands[x], x))

            for c in cand_list:
                local_best_delta = None
                local_best_pos = 0
                for pos in range(len(route) + 1):
                    delta = insertion_cost(route, c, pos)
                    if local_best_delta is None or delta < local_best_delta or (delta == local_best_delta and pos < local_best_pos):
                        local_best_delta = delta
                        local_best_pos = pos
                if best_delta is None or local_best_delta < best_delta or (local_best_delta == best_delta and c < best_node):
                    best_delta = local_best_delta
                    best_node = c
                    best_pos = local_best_pos

            if best_node is None:
                break

            route.insert(best_pos, best_node)
            load += demands[best_node]
            del unassigned[best_node]

        routes.append(route)
        loads.append(load)

