                        improved = True
                        break
                if improved:
                    break
        routes[idx] = r

    # Inter-route relocate improvement
    improved = True
    while improved:
        improved = False
        best_gain = 0.0
        best_move = None  # (from_r, to_r, node_idx, pos)

        for i in range(len(routes)):
            ri = routes[i]
            li = route_load(ri)
            for p, node in enumerate(ri):
